+                    + BQVectorUtils.discretize(vector.length, 64)
+                    + " [ "
+                    + this.discretizedDimensions
+                    + " ]"
+                    + "!= "
+                    + destination.length
+                    + " * 8"
+            );
+        }
+
+        if (vector.length != centroid.length) {
